for (const [spanish, valencian] of Object.entries(valencianText)) {
  if (!Object.hasOwn(spanishText, valencian)) spanishText[valencian] = spanish;
}

const storySlug = title => title
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, "-")
  .replace(/^-|-$/g, "");

for (const card of document.querySelectorAll(".story-card, .news-card")) {
  const title = card.querySelector(".story-content h2 a, .story-content h3 a");
  if (!title) continue;

  const articleUrl = `noticia.html?id=${storySlug(title.textContent.trim())}`;
  for (const link of card.querySelectorAll("a")) link.href = articleUrl;
}

const languageToggle = document.querySelector("#language-toggle");
const translatableAttributes = ["alt", "aria-label", "content", "placeholder", "title", "value"];

function setLanguage(language) {
  const isValencian = language === "val";
  const dictionary = isValencian ? valencianText : spanishText;
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  const translate = value => {
    if (Object.hasOwn(dictionary, value)) return dictionary[value];
    const prefix = Object.keys(dictionary)
      .filter(key => key.length > 12 && value.startsWith(key) && /[\s«]/.test(value[key.length] || ""))
      .sort((left, right) => right.length - left.length)[0];
    return prefix ? dictionary[prefix] + value.slice(prefix.length) : value;
  };

  while (walker.nextNode()) {
    const node = walker.currentNode;
    if (node.parentElement.closest("script, style")) continue;
    const originalText = node.nodeValue;
    const trimmedText = originalText.trim();
    const translatedText = translate(trimmedText);
    if (translatedText !== trimmedText) node.nodeValue = originalText.replace(trimmedText, translatedText);
  }

  for (const element of document.querySelectorAll(translatableAttributes.map(attribute => `[${attribute}]`).join(","))) {
    for (const attribute of translatableAttributes) {
      const value = element.getAttribute(attribute);
      if (value) element.setAttribute(attribute, translate(value));
    }
  }

  document.documentElement.lang = isValencian ? "ca-valencia" : "es";
  const titleSuffix = " — El Vèrtex";
  const hasTitleSuffix = document.title.endsWith(titleSuffix);
  const titleText = hasTitleSuffix ? document.title.slice(0, -titleSuffix.length) : document.title;
  document.title = `${translate(titleText)}${hasTitleSuffix ? titleSuffix : ""}`;
  if (languageToggle) {
    languageToggle.textContent = isValencian ? "Castellano" : "Valencià";
    languageToggle.setAttribute("aria-label", isValencian ? "Canvia a castellà" : "Cambiar a valenciano");
  }
  window.elvertexLanguage = language;
  document.dispatchEvent(new Event("languagechange"));
}

window.elvertexSetLanguage = setLanguage;

const carouselTrack = document.querySelector(".story-grid");
const carouselViewport = document.querySelector(".carousel-viewport");
const carouselCards = [...document.querySelectorAll(".story-card")];
const carouselDots = [...document.querySelectorAll(".carousel-dot-button")];
let activeSlide = 0;

if (languageToggle) {
  languageToggle.addEventListener("click", () => {
    setLanguage(document.documentElement.lang === "es" ? "val" : "es");
  });
}

if (carouselTrack && carouselViewport && carouselCards.length) {
  function showSlide(index) {
    activeSlide = (index + carouselCards.length) % carouselCards.length;
    carouselTrack.style.transform = `translateX(-${activeSlide * 100}%)`;
    carouselDots.forEach((dot, dotIndex) => {
      if (dotIndex === activeSlide) dot.setAttribute("aria-current", "true");
      else dot.removeAttribute("aria-current");
    });
  }

  document.querySelector(".carousel-previous")?.addEventListener("click", () => showSlide(activeSlide - 1));
  document.querySelector(".carousel-next")?.addEventListener("click", () => showSlide(activeSlide + 1));
  carouselDots.forEach((dot, index) => {
    dot.addEventListener("click", () => showSlide(index));
  });

  let swipeStartX = null;
  carouselViewport.addEventListener("pointerdown", event => {
    if (event.pointerType === "touch") swipeStartX = event.clientX;
  });
  carouselViewport.addEventListener("pointerup", event => {
    if (swipeStartX === null) return;
    const swipeDistance = swipeStartX - event.clientX;
    if (Math.abs(swipeDistance) > 40) showSlide(activeSlide + (swipeDistance > 0 ? 1 : -1));
    swipeStartX = null;
  });
  carouselViewport.addEventListener("pointercancel", () => {
    swipeStartX = null;
  });
}

setLanguage(document.documentElement.lang.startsWith("ca") ? "val" : "es");
